function referenceReviewCard(array $r,bool $duplicate=false):string{ob_start();?><article class="ref-review-card" <?=$duplicate?'aria-hidden="true"':''?>><?php if($r['isSample']??false):?><span class="sample-label">Sample review</span><?php endif;?><?php if($r['quote']!==''):?><p>“<?=esc($r['quote'])?>”<?=!empty($r['isExcerpt'])?' …':''?></p><?php else:?><p class="rating-only">Rating only — no written review.</p><?php endif;?><hr><h3><?=esc($r['author'])?></h3><span><?=esc($r['sourceDate']??$r['location'])?></span><?php if(!empty($r['source'])):?><a class="review-source" href="<?=esc($r['source'])?>" target="_blank" rel="noopener noreferrer" <?=$duplicate?'tabindex="-1"':''?>>Read original on <?=esc($r['sourcePlatform']??'Google')?> ↗</a><?php endif;?><div class="review-stars" aria-label="<?=esc($r['rating'])?> out of 5"><?php for($i=0;$i<(int)$r['rating'];$i++):?>★<?php endfor;?></div></article><?php return ob_get_clean();}
function referenceReviews():string{
 $reviews=records('reviews');if(!$reviews)return '';$google=array_values(array_filter($reviews,fn($r)=>($r['sourcePlatform']??'')==='Google'));ob_start();?><section class="section ref-reviews"><div class="container"><?=referenceHeading('Guest stories &','shared moments','/assets/coast-small.webp','Genuine feedback from our Google business profile. Review excerpts link to the original.')?><?php if($google):?><div class="google-review-summary"><strong><?=number_format(array_sum(array_column($google,'rating'))/count($google),1)?> / 5</strong><span><?=count($google)?> Google reviews · imported October 2026</span><a href="https://share.google/WEvlAw32eoehb4DHq" target="_blank" rel="noopener noreferrer">View our Google profile ↗</a></div><?php endif;?><div class="ref-review-window" id="reviews" tabindex="0" aria-label="Guest reviews moving in alternating vertical columns"><div class="ref-review-columns"><?php for($lane=0;$lane<3;$lane++):?><div class="ref-review-lane"><div><?php $subset=array_values(array_filter($reviews,fn($r,$i)=>$i%3===$lane,ARRAY_FILTER_USE_BOTH));foreach([$subset,$subset] as $copy=>$items)foreach($items as $r)echo referenceReviewCard($r,(bool)$copy);?></div></div><?php endfor;?></div><div class="ref-mobile-review-lane"><div><?php foreach([$reviews,$reviews] as $copy=>$items)foreach($items as $r)echo referenceReviewCard($r,(bool)$copy);?></div></div></div></div></section><?php return ob_get_clean();}
