igation"><div class="container"><nav aria-label="Footer navigation"><a href="/">Home</a><a href="/tours">Tours</a><a href="/hotel-booking">Hotels</a><a href="/guides">Travel journal</a><a href="/about">About us</a><a href="/contact">Contact</a></nav><a class="button button-white" href="/account">My travel account <?=commerceIcon('user')?></a></div></div><div class="ref-footer-bottom container"><p>Copyright © <?=gmdate('Y')?> <strong>Desert Sky Tourism</strong></p><div><a href="/terms">Booking terms</a><a href="/privacy">Privacy policy</a></div><div class="ref-footer-socials"><?php if(!empty($s['facebook'])):?><a href="<?=esc($s['facebook'])?>" target="_blank" rel="noopener noreferrer" aria-label="Desert Sky on Facebook">f</a><?php endif;if(!empty($s['instagram'])):?><a href="<?=esc($s['instagram'])?>" target="_blank" rel="noopener noreferrer" aria-label="Desert Sky on Instagram">◎</a><?php endif;?><a href="https://wa.me/<?=preg_replace('/\D/','',$s['whatsapp'])?>" target="_blank" rel="noopener noreferrer" aria-label="Chat on WhatsApp"><?=premiumIcon('message')?></a></div></div></footer><?php return ob_get_clean();}
function referenceSteps(string $title='From inspiration to your next great day.'):string{ob_start();?><section class="section ref-planning"><div class="container"><?=referenceHeading('A little planning.',$title,'/assets/coast-small.webp')?><div class="ref-step-grid"><?php foreach([['01','Find your experience','Browse by destination or follow your interests — a city landmark, a desert escape, a family outing or a day on the water.'],['02','Make the details yours','Choose your travel date and guest numbers. Read what is included and add only the optional extras you want. Ask us about anything that needs a personal touch.'],['03','Book with clarity','Review the total before secure payment. Your paid booking is saved to your signed-in account, and our team confirms the arrangements separately.']] as [$n,$h,$p]):?><article><span><?=$n?></span><h3><?=$h?></h3><p><?=$p?></p></article><?php endforeach;?></div></div></section><?php return ob_get_clean();}
