function referencePageExtras(string $path,?array $record):string{if($path==='/'||$path==='/cart'||str_starts_with($path,'/account')||in_array($path,['/booking','/thank-you','/terms','/privacy']))return '';ob_start();if($path==='/tours'||str_starts_with($path,'/destinations/')){$location=str_starts_with($path,'/destinations/')?findSlug('locations',substr($path,14)):null;$name=$location['title']??'the UAE';$copy=match($location['id']??''){ 'abu-dhabi'=>'Make time for grand architecture, cultural landmarks and days by the water. Abu Dhabi offers a different rhythm: unhurried discovery, memorable museums and a skyline framed by the Arabian Gulf.','ras-al-khaimah'=>'Leave room in your itinerary for a change of scenery. Ras Al Khaimah brings coastal stays, heritage landmarks and desert landscapes together for a day that feels a little further from the everyday.',default=>'Follow the energy of the city, step into a quieter corner of the desert, or watch the skyline from the water. The best itinerary makes space for the things you love — and a few things you did not expect.'};?><section class="container section ref-story-split"><img src="<?=esc($location['image']??'/assets/coast.webp')?>" alt="<?=esc($name)?> travel inspiration" width="1000" height="900" loading="lazy"><div><span class="eyebrow">Make your own way</span><h2>More ways to experience <?=esc($name)?>.</h2><p><?=esc($copy)?></p><p>Start with one experience or build a few favourites into your cart. Private vehicle tours, attraction visits and optional activities each have their own arrangements, so check the details on your selected tour before booking.</p><p>Need something more specific? Share your group size, hotel area and interests. Our Dubai-based team can discuss suitable options and the details that matter to your day.</p><a class="button button-outline" href="/contact">Ask a local travel team <?=icon()?></a></div></section><?=referenceSteps()?><?php }
elseif(str_starts_with($path,'/tours/')){$category=$record['category']??'';$desert=$category==='Desert adventures';?><section class="section ref-tour-planning"><div class="container"><?=referenceHeading('Before your next','great adventure','/assets/coast-small.webp')?><div class="ref-step-grid"><article><span><?=icon('sun')?></span><h3><?=$desert?'Dress for the desert':'Come ready to explore'?></h3><p><?=$desert?'Choose comfortable clothing and closed shoes. Bring sun protection for daylight hours and a light layer for cooler evenings. Keep personal belongings secure during activities.':'Wear comfortable clothing and footwear suited to your selected experience. Bring sun protection for outdoor stops and check venue dress requirements before your visit.'?></p></article><article><span><?=icon('pin')?></span><h3>Make pickup simpler</h3><p>Share your hotel name, area and a reachable phone number. Pickup eligibility, meeting points and timings vary by tour and will be confirmed with your arrangements.</p></article><article><span><?=premiumIcon('users')?></span><h3>A day for your group</h3><p>Tell us about children, access needs or special requests before paying. Age limits, activity restrictions and transfer capacity can vary by the selected experience and supplier.</p></article></div></div></section><?php }
elseif($path==='/about'){?><section class="section ref-values"><div class="container"><?=referenceHeading('Your journey.','Our attention to the details.','/assets/dubai-small.webp')?><div class="ref-step-grid"><article><span><?=premiumIcon('compass')?></span><h3>Start with curiosity</h3><p>We believe the most memorable trips begin with what interests you. Whether it is a first skyline view, an unfamiliar neighbourhood or an evening in the dunes, your interests shape the conversation.</p></article><article><span><?=premiumIcon('message')?></span><h3>Keep things personal</h3><p>A website can show the possibilities. A conversation can make the details clearer. We help with questions about your group, timings, private arrangements and the experience you are considering.</p></article><article><span><?=icon('shield')?></span><h3>Make room for clarity</h3><p>Good travel plans start with clear expectations. Review your selected inclusions and cancellation terms, ask questions in advance, and let our team confirm the final arrangements.</p></article></div></div></section><?=referenceSteps('A more thoughtful way to travel.')?><?php }
elseif($path==='/hotel-booking'){?><section class="section ref-hotel-details"><div class="container"><?=referenceHeading('A stay that fits','the way you travel.','/assets/coast-small.webp','Help us understand your plans so we can discuss suitable stay options.')?><div class="ref-hotel-grid"><?php foreach([['Your travel dates','Share check-in and check-out dates, plus any flexibility you have. Availability and rates depend on the property and dates.'],['Your preferred area','Choose the neighbourhood that fits your plans: near the beach, convenient for city sightseeing, or close to the places you need to be.'],['Who is travelling','Tell us the number of adults and children, room requirements and children’s ages where applicable.'],['Your comfort preferences','Let us know about meal preferences, room type, access needs and any specific facilities that matter to your stay.'],['Your budget','Give us an approximate budget in AED and whether it is per night or for the whole stay. We can discuss the possibilities.'],['Transfers and experiences','If you need airport transfers or would like to combine a stay with tours, mention them in your enquiry so the arrangements can be discussed together.']] as [$h,$p]):?><article><span><?=icon('check')?></span><h3><?=$h?></h3><p><?=$p?></p></article><?php endforeach;?></div><div class="notice">Hotel enquiries are requests for assistance, not confirmed reservations. Property availability, final rates, taxes, payment and cancellation conditions must be confirmed before a booking is made.</div></div></section><?php }
elseif($path==='/contact'){?><section class="section ref-contact-steps"><div class="container"><?=referenceHeading('From your first hello','to a day worth remembering.','/assets/dubai-small.webp')?><div class="ref-step-grid"><article><span>01</span><h3>Tell us the outline</h3><p>Share your dates, the number of travellers and where you are staying. Include any experiences that have already caught your eye.</p></article><article><span>02</span><h3>Talk through the details</h3><p>Ask about transfer areas, private options, attraction choices or special requests. If an experience shows no price, request a current quote.</p></article><article><span>03</span><h3>Review before you book</h3><p>Check your selected arrangements, inclusions and cancellation conditions. For an existing booking, include your booking reference so we can help more easily.</p></article></div></div></section><?php }
elseif($path==='/guides'||str_starts_with($path,'/guides/')){?><section class="section ref-journal-extra"><div class="container"><?=referenceHeading('Turn inspiration into','your own UAE story.','/assets/coast-small.webp','Use our guides as a starting point, then explore the experiences that match your interests.')?><div class="ref-guide-destinations"><?php foreach(records('locations') as $l):?><a href="<?=esc(pathFor($l,'locations'))?>"><?=photo($l)?><div><h3><?=esc($l['title'])?></h3><p><?=esc($l['summary'])?></p><span class="text-link">Explore experiences <?=icon()?></span></div></a><?php endforeach;?></div></div></section><?php }
if($path==='/about'||$path==='/contact'||$path==='/hotel-booking'||$path==='/tours'||str_starts_with($path,'/destinations/')){?><section class="container section ref-practical-faq"><div><span class="eyebrow">A little clarity</span><h2>Good to know<br>before you go.</h2><p>Every experience has its own details. Ask us about anything that matters to your travel plans.</p></div><div><?php foreach([['Can I book more than one experience?','Yes. Choose the date, guests and extras for a priced experience, then add it to your cart. You can add more experiences before reviewing the combined total at checkout.'],['Will my booking appear in my account?','Bookings made while signed in, or while creating an account at checkout, appear in My bookings after successful payment verification. Guest bookings are not automatically claimed by matching an email address.'],['Are all experiences available for online payment?','Only experiences with a current listed price can be paid online. Other listings are enquiry-only until a price is supplied. Our team can discuss availability and arrangements with you.'],['What does a paid booking mean?','A successful payment records your booking request. Our team confirms the tour arrangements separately. Review the individual cancellation conditions before payment; cancelling a tour does not automatically issue a refund.']] as [$q,$a]):?><details class="faq"><summary><?=$q?><span>+</span></summary><p><?=$a?></p></details><?php endforeach;?></div></section><?php }echo referenceCTA();return ob_get_clean();}
